-- ============================================================
-- E-Commerce Sales & Customer Analytics
-- File: 04_advanced_business_analysis.sql
-- Purpose: Extend the project with advanced business insights using
--          cumulative analysis, segmentation, date functions, and CTEs.
-- Database: SQLite
-- Source table: ecommerce_orders
-- ============================================================


-- 1. Product Revenue Contribution and Cumulative Pareto Analysis
-- Business question:
-- How much of total revenue is generated by the highest-revenue products,
-- and how many products account for approximately 80% of revenue?
-- Purpose:
-- Rank products by revenue and calculate their cumulative contribution.
-- This is a Pareto-style analysis; the results show the observed contribution
-- and do not assume that the 80/20 rule must hold exactly.
WITH product_revenue AS (
    SELECT
        product_id,
        product_name,
        category,
        SUM(quantity * unit_price) AS total_revenue
    FROM ecommerce_orders
    GROUP BY product_id, product_name, category
),
product_contribution AS (
    SELECT
        product_id,
        product_name,
        category,
        total_revenue,
        SUM(total_revenue) OVER (
            ORDER BY total_revenue DESC, product_id
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        ) AS cumulative_revenue,
        SUM(total_revenue) OVER () AS overall_revenue
    FROM product_revenue
)
SELECT
    product_id,
    product_name,
    category,
    ROUND(total_revenue, 2) AS total_revenue,
    ROUND(total_revenue * 100.0 / NULLIF(overall_revenue, 0), 2)
        AS revenue_percentage,
    ROUND(cumulative_revenue, 2) AS cumulative_revenue,
    ROUND(cumulative_revenue * 100.0 / NULLIF(overall_revenue, 0), 2)
        AS cumulative_revenue_percentage
FROM product_contribution
ORDER BY total_revenue DESC, product_id;


-- 2. Order Value Segmentation
-- Business question:
-- How are orders distributed across low-, medium-, and high-value bands?
-- Purpose:
-- Segment individual orders using quartiles, then compare order count
-- and revenue contribution across the four relative value groups.
-- Note: Bands are relative to this dataset and may have different thresholds
-- when the dataset changes.
WITH order_values AS (
    SELECT
        order_id,
        SUM(quantity * unit_price) AS order_value
    FROM ecommerce_orders
    WHERE order_id IS NOT NULL
    GROUP BY order_id
),
scored_orders AS (
    SELECT
        order_id,
        order_value,
        NTILE(4) OVER (ORDER BY order_value) AS value_quartile
    FROM order_values
)
SELECT
    CASE value_quartile
        WHEN 1 THEN 'Q1 - Lowest order value'
        WHEN 2 THEN 'Q2 - Lower-middle order value'
        WHEN 3 THEN 'Q3 - Upper-middle order value'
        WHEN 4 THEN 'Q4 - Highest order value'
    END AS order_value_segment,
    COUNT(*) AS total_orders,
    ROUND(SUM(order_value), 2) AS total_revenue,
    ROUND(AVG(order_value), 2) AS average_order_value,
    ROUND(
        SUM(order_value) * 100.0
        / (SELECT SUM(order_value) FROM order_values),
        2
    ) AS revenue_percentage
FROM scored_orders
GROUP BY value_quartile
ORDER BY value_quartile;


-- 3. Sales Performance by Day of Week
-- Business question:
-- Which days of the week have the highest order volume and revenue?
-- Purpose:
-- Compare orders, quantity sold, and revenue by weekday.
-- SQLite %w values are 0 for Sunday through 6 for Saturday.
SELECT
    CAST(strftime('%w', date(order_date)) AS INTEGER) AS weekday_number,
    CASE strftime('%w', date(order_date))
        WHEN '0' THEN 'Sunday'
        WHEN '1' THEN 'Monday'
        WHEN '2' THEN 'Tuesday'
        WHEN '3' THEN 'Wednesday'
        WHEN '4' THEN 'Thursday'
        WHEN '5' THEN 'Friday'
        WHEN '6' THEN 'Saturday'
    END AS weekday_name,
    COUNT(DISTINCT order_id) AS total_orders,
    SUM(quantity) AS total_quantity_sold,
    ROUND(SUM(quantity * unit_price), 2) AS total_revenue,
    ROUND(
        SUM(quantity * unit_price) * 1.0
        / NULLIF(COUNT(DISTINCT order_id), 0),
        2
    ) AS average_order_value
FROM ecommerce_orders
WHERE order_date IS NOT NULL
GROUP BY weekday_number, weekday_name
ORDER BY weekday_number;


-- 4. Time from Customer Signup to First Purchase
-- Business question:
-- How long does it take customers to make their first purchase after signup?
-- Purpose:
-- Calculate the elapsed days between signup and first recorded order,
-- then summarize the distribution of that delay.
-- Customers with missing dates or a first order before signup are excluded
-- from the delay summary and should be reviewed separately if present.
WITH customer_dates AS (
    SELECT
        customer_id,
        MIN(date(signup_date)) AS signup_date,
        MIN(date(order_date)) AS first_order_date
    FROM ecommerce_orders
    WHERE customer_id IS NOT NULL
    GROUP BY customer_id
),
signup_delays AS (
    SELECT
        customer_id,
        signup_date,
        first_order_date,
        CAST(
            julianday(first_order_date) - julianday(signup_date)
            AS INTEGER
        ) AS days_to_first_purchase
    FROM customer_dates
    WHERE signup_date IS NOT NULL
      AND first_order_date IS NOT NULL
      AND date(first_order_date) >= date(signup_date)
)
SELECT
    COUNT(*) AS customers_with_valid_dates,
    ROUND(AVG(days_to_first_purchase), 2) AS average_days_to_first_purchase,
    MIN(days_to_first_purchase) AS minimum_days_to_first_purchase,
    MAX(days_to_first_purchase) AS maximum_days_to_first_purchase,
    SUM(CASE WHEN days_to_first_purchase = 0 THEN 1 ELSE 0 END)
        AS purchased_on_signup_date,
    ROUND(
        SUM(CASE WHEN days_to_first_purchase = 0 THEN 1 ELSE 0 END)
        * 100.0 / NULLIF(COUNT(*), 0),
        2
    ) AS same_day_purchase_percentage
FROM signup_delays;


-- 5. Product Sales Efficiency Profile
-- Business question:
-- Which products combine strong sales volume with strong revenue generation?
-- Purpose:
-- Compare each product's quantity sold, revenue, and average revenue per unit.
-- The profile labels use dataset-relative median values, not profit margins.
WITH product_metrics AS (
    SELECT
        product_id,
        product_name,
        category,
        SUM(quantity) AS total_quantity_sold,
        SUM(quantity * unit_price) AS total_revenue,
        SUM(quantity * unit_price) * 1.0
            / NULLIF(SUM(quantity), 0) AS revenue_per_unit
    FROM ecommerce_orders
    GROUP BY product_id, product_name, category
),
product_thresholds AS (
    SELECT
        *,
        NTILE(2) OVER (ORDER BY total_quantity_sold) AS quantity_group,
        NTILE(2) OVER (ORDER BY total_revenue) AS revenue_group
    FROM product_metrics
)
SELECT
    product_id,
    product_name,
    category,
    total_quantity_sold,
    ROUND(total_revenue, 2) AS total_revenue,
    ROUND(revenue_per_unit, 2) AS revenue_per_unit,
    CASE
        WHEN quantity_group = 2 AND revenue_group = 2
            THEN 'High volume / high revenue'
        WHEN quantity_group = 2 AND revenue_group = 1
            THEN 'High volume / lower revenue'
        WHEN quantity_group = 1 AND revenue_group = 2
            THEN 'Lower volume / high revenue'
        ELSE 'Lower volume / lower revenue'
    END AS product_performance_segment
FROM product_thresholds
ORDER BY total_revenue DESC, total_quantity_sold DESC;


-- 6. Data Check: Signup Date Before First Purchase
-- Business question:
-- Are there customers whose recorded first purchase predates their signup date?
-- Purpose:
-- Flag potentially inconsistent customer timeline records for review.
-- An empty result means no customer with both dates has this condition.
WITH customer_dates AS (
    SELECT
        customer_id,
        MIN(date(signup_date)) AS signup_date,
        MIN(date(order_date)) AS first_order_date
    FROM ecommerce_orders
    WHERE customer_id IS NOT NULL
    GROUP BY customer_id
)
SELECT
    customer_id,
    signup_date,
    first_order_date,
    CAST(
        julianday(first_order_date) - julianday(signup_date)
        AS INTEGER
    ) AS days_from_signup_to_first_purchase
FROM customer_dates
WHERE signup_date IS NOT NULL
  AND first_order_date IS NOT NULL
  AND date(first_order_date) < date(signup_date)
ORDER BY days_from_signup_to_first_purchase;
